{
  "cards": [
    {
      "ref": "c1",
      "type": "concept",
      "title": "Definição de Hipoglicemia",
      "question": "O que é hipoglicemia no adulto?",
      "answer": "Glicemia abaixo de 70 mg/dL",
      "sourceExcerpt": "Hipoglicemia é a glicemia abaixo de 70 mg/dL.",
      "payload": {}
    },
    {
      "ref": "c2",
      "type": "concept",
      "title": "Causas na Diabetes",
      "question": "Quais são as causas de hipoglicemia em pacientes com diabetes?",
      "answer": "Dose excessiva de insulina, refeição atrasada ou exercício sem ajuste",
      "sourceExcerpt": "Em pessoas com diabetes, ela costuma aparecer após dose excessiva de insulina, refeição atrasada ou exercício sem ajuste.",
      "payload": {}
    },
    {
      "ref": "c3",
      "type": "concept",
      "title": "Sintomas Autonômicos",
      "question": "Quais são os sintomas autonômicos da hipoglicemia?",
      "answer": "Tremor, sudorese, palpitação e fome",
      "sourceExcerpt": "Os sintomas autonômicos incluem tremor, sudorese, palpitação e fome.",
      "payload": {}
    },
    {
      "ref": "c4",
      "type": "concept",
      "title": "Sintomas Neuroglicopênicos",
      "question": "Quais são os sintomas neuroglicopênicos da hipoglicemia?",
      "answer": "Confusão, alteração de comportamento, convulsão e coma",
      "sourceExcerpt": "Os sintomas neuroglicopênicos incluem confusão, alteração de comportamento, convulsão e coma.",
      "payload": {}
    },
    {
      "ref": "c5",
      "type": "concept",
      "title": "Tratamento Inicial Consciente",
      "question": "Qual o tratamento inicial para um paciente consciente com hipoglicemia?",
      "answer": "Oferecer 15 gramas de carboidrato de absorção rápida por via oral e medir a glicemia em 15 minutos",
      "sourceExcerpt": "No paciente consciente, o tratamento inicial é oferecer 15 gramas de carboidrato de absorção rápida por via oral e medir a glicemia de novo em 15 minutos.",
      "payload": {}
    },
    {
      "ref": "c6",
      "type": "concept",
      "title": "Tratamento Não Oral",
      "question": "Como tratar um paciente inconsciente ou que não consegue engolir com hipoglicemia?",
      "answer": "Administrar glicose por via intravenosa; sem acesso venoso, usar glucagon por via intramuscular",
      "sourceExcerpt": "No paciente inconsciente ou que não consegue engolir, administra-se glicose por via intravenosa. Sem acesso venoso, pode-se usar glucagon por via intramuscular.",
      "payload": {}
    },
    {
      "ref": "c7",
      "type": "concept",
      "title": "Acompanhamento Pós-Correção",
      "question": "O que fazer após corrigir a hipoglicemia?",
      "answer": "Procura-se a causa e ajusta-se o esquema de tratamento para evitar novos episódios",
      "sourceExcerpt": "Depois da correção, procura-se a causa e ajusta-se o esquema de tratamento para evitar novos episódios.",
      "payload": {}
    },
    {
      "ref": "c8",
      "type": "concept",
      "title": "Fluxo de Atendimento",
      "question": "Qual é o fluxo de atendimento para hipoglicemia?",
      "answer": "Confirmar glicemia capilar → avaliar consciência e engolir → tratar por via oral ou venosa → medir novamente → investigar causa",
      "sourceExcerpt": "Fluxo de atendimento da hipoglicemia\n1. Confirmar a glicemia capilar.\n2. Avaliar se o paciente está consciente e consegue engolir.\n3. Tratar por via oral ou venosa conforme a avaliação.\n4. Medir a glicemia de novo em 15 minutos.\n5. Investigar a causa do episódio.",
      "payload": {
        "steps": [
          {
            "id": "s1",
            "text": "Confirmar a glicemia capilar."
          },
          {
            "id": "s2",
            "text": "Avaliar se o paciente está consciente e consegue engolir."
          },
          {
            "id": "s3",
            "text": "Tratar por via oral ou venosa conforme a avaliação."
          },
          {
            "id": "s4",
            "text": "Medir a glicemia de novo em 15 minutos."
          },
          {
            "id": "s5",
            "text": "Investigar a causa do episódio."
          }
        ]
      }
    },
    {
      "ref": "c9",
      "type": "concept",
      "title": "Cetoacidose Diabética",
      "question": "O que é cetoacidose diabética?",
      "answer": "Complicação aguda do diabetes causada por deficiência de insulina, combinando hiperglicemia, cetose e acidose metabólica",
      "sourceExcerpt": "A cetoacidose diabética é uma complicação aguda do diabetes causada por deficiência de insulina. Ela combina hiperglicemia, cetose e acidose metabólica.",
      "payload": {}
    },
    {
      "ref": "c10",
      "type": "concept",
      "title": "Fatores Précipantes da Cetoacidose",
      "question": "Quais são os fatores precipitantes mais comuns da cetoacidose diabética?",
      "answer": "Infecção, interrupção da insulina e diabetes ainda não diagnosticado",
      "sourceExcerpt": "Os fatores precipitantes mais comuns são infecção, interrupção da insulina e diabetes ainda não diagnosticado.",
      "payload": {}
    },
    {
      "ref": "c11",
      "type": "concept",
      "title": "Sintomas da Cetoacidose",
      "question": "Quais são os sinais clínicos da cetoacidose diabética?",
      "answer": "Poliúria, polidipsia, náuseas, vômitos, dor abdominal, desidratação e respiração rápida e profunda (respiração de Kussmaul)",
      "sourceExcerpt": "O quadro clínico inclui poliúria, polidipsia, náuseas, vômitos, dor abdominal, desidratação e respiração rápida e profunda, chamada respiração de Kussmaul.",
      "payload": {}
    },
    {
      "ref": "c12",
      "type": "concept",
      "title": "Tratamento da Cetoacidose",
      "question": "Quais são os pilares do tratamento da cetoacidose diabética?",
      "answer": "Hidratação venosa, insulina venosa e reposição de potássio conforme o nível sérico",
      "sourceExcerpt": "O tratamento se apoia em três pilares: hidratação venosa, insulina venosa e reposição de potássio conforme o nível sérico.",
      "payload": {}
    }
  ],
